def compute(vars):
    old_balance = vars["v2"]
    new_balance = vars["v1"]
    change = new_balance - old_balance

    return {
        "value": change,
        "trace": {
            "old_balance": old_balance,
            "new_balance": new_balance,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
